func (this *Okx) fetchTimeBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetPublicTime(params)).Raw))
	//
	//     {
	//         "code": "0",
	//         "data": [
	//             {"ts": "1621247923668"}
	//         ],
	//         "msg": ""
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var first map[string]any = SafeMapTyped(data, 0)

	ch <- this.SafeInteger(first, "ts")
	return nil
}

/**
 * @method
 * @name okx#fetchAccounts
 * @description fetch all the accounts associated with a profile
 * @see https://www.okx.com/docs-v5/en/#trading-account-rest-api-get-account-configuration
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [account structures]{@link https://docs.ccxt.com/?id=account-structure} indexed by the account type
 */
