func (this *Okx) fetchDepositAddressesByNetworkBody(ch chan any, code any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"ccy": currency["id"],
	}

	response := (<-this.PrivateGetAssetDepositAddress(this.Extend(request, params)))
	PanicOnError(response)
	//
	//     {
	//         "code": "0",
	//         "msg": "",
	//         "data": [
	//             {
	//                 "addr": "okbtothemoon",
	//                 "memo": "971668", // may be missing
	//                 "tag":"52055", // may be missing
	//                 "pmtId": "", // may be missing
	//                 "ccy": "BTC",
	//                 "to": "6", // 1 SPOT, 3 FUTURES, 6 FUNDING, 9 SWAP, 12 OPTION, 18 Unified account
	//                 "selected": true
	//             },
	//             // {"ccy":"usdt-erc20","to":"6","addr":"0x696abb81974a8793352cbd33aadcf78eda3cfdfa","selected":true},
	//             // {"ccy":"usdt-trc20","to":"6","addr":"TRrd5SiSZrfQVRKm4e9SRSbn2LNTYqCjqx","selected":true},
	//             // {"ccy":"usdt_okexchain","to":"6","addr":"0x696abb81974a8793352cbd33aadcf78eda3cfdfa","selected":true},
	//             // {"ccy":"usdt_kip20","to":"6","addr":"0x696abb81974a8793352cbd33aadcf78eda3cfdfa","selected":true},
	//         ]
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var filtered []any = this.FilterBy(data, "selected", true)
	var parsed any = this.ParseDepositAddresses(filtered, []any{currency["code"]}, false)

	ch <- this.IndexBy(parsed, "network")
	return nil
}

/**
 * @method
 * @name okx#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://www.okx.com/docs-v5/en/#funding-account-rest-api-get-deposit-address
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.network] the network name for the deposit address
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Okx) FetchDepositAddressAsync(code any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Okx) fetchDepositAddressBody(ch chan any, code any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var rawNetwork *string = this.SafeString(params, "network") // some networks are like "Dora Vota Mainnet"
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, "network"))
	var codeValue *string = this.SafeCurrencyCode(code)
	var network *string = this.NetworkIdToCode(rawNetwork, codeValue)

	responseRaw := (<-this.FetchDepositAddressesByNetworkAsync(codeValue, paramsOmitted))
	PanicOnError(responseRaw)
	var response any = responseRaw
	if network != nil {
		var result any = this.SafeDict(response, network)
		if IsEqual(result, nil) {
			panic(InvalidAddress(this.Id + " fetchDepositAddress() cannot find " + *network + " deposit address for " + *codeValue))
		}

		ch <- result
		return nil
	}
	var codeNetwork *string = this.NetworkIdToCode(codeValue, codeValue)
	if (codeNetwork != nil) && (InOp(response, codeNetwork)) {

		ch <- GetValue(response, codeNetwork)
		return nil
	}
	// if the network is not specified, return the first address
	var keys []string = ObjectKeys(response)
	var first *string = this.SafeString(keys, 0, "")

	ch <- this.SafeDict(response, first)
	return nil
}

/**
 * @method
 * @name okx#withdraw
 * @description make a withdrawal
 * @see https://www.okx.com/docs-v5/en/#funding-account-rest-api-withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {string} tag
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
