func (this *Okx) ParseTransactionStatus(status *string) *string {
	//
	// deposit statuses
	//
	//     {
	//         "0": "waiting for confirmation",
	//         "1": "deposit credited",
	//         "2": "deposit successful"
	//     }
	//
	// withdrawal statuses
	//
	//     {
	//        '-3': "pending cancel",
	//        "-2": "canceled",
	//        "-1": "failed",
	//         "0": "pending",
	//         "1": "sending",
	//         "2": "sent",
	//         "3": "awaiting email verification",
	//         "4": "awaiting manual verification",
	//         "5": "awaiting identity verification"
	//     }
	//
	var statuses map[string]any = map[string]any{
		"-3": "pending",
		"-2": "canceled",
		"-1": "failed",
		"0":  "pending",
		"1":  "pending",
		"2":  "ok",
		"3":  "pending",
		"4":  "pending",
		"5":  "pending",
		"6":  "pending",
		"7":  "pending",
		"8":  "pending",
		"9":  "pending",
		"10": "pending",
		"12": "pending",
		"15": "pending",
		"16": "pending",
	}
	if status == nil {
		return nil
	}
	return this.SafeString(statuses, status, status)
}
func (this *Okx) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// withdraw
	//
	//     {
	//         "amt": "0.1",
	//         "wdId": "67485",
	//         "ccy": "BTC"
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "amt": "0.094",
	//         "wdId": "4703879",
	//         "fee": "0.01000000eth",
	//         "txId": "0x62477bac6509a04512819bb1455e923a60dea5966c7caeaa0b24eb8fb0432b85",
	//         "ccy": "ETH",
	//         "from": "13426335357",
	//         "to": "0xA41446125D0B5b6785f6898c9D67874D763A1519",
	//         "tag",
	//         "pmtId",
	//         "memo",
	//         "ts": "1597026383085",
	//         "state": "2"
	//     }
	//
	// fetchDeposits
	//
	//     {
	//         "amt": "0.01044408",
	//         "txId": "1915737_3_0_0_asset",
	//         "ccy": "BTC",
	//         "from": "13801825426",
	//         "to": "",
	//         "ts": "1597026383085",
	//         "state": "2",
	//         "depId": "4703879"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var typeVar string
	var id *string = nil
	var withdrawalId *string = this.SafeString(transaction, "wdId")
	var addressFrom *string = this.SafeString(transaction, "from")
	var addressTo *string = this.SafeString(transaction, "to")
	var address *string = addressTo
	var tagTo *string = this.SafeString2(transaction, "tag", "memo")
	if tagTo == nil {
		tagTo = this.SafeString(transaction, "pmtId")
	} else {
		tagTo = this.SafeString2(transaction, "pmtId", tagTo)
	}
	if withdrawalId != nil {
		typeVar = "withdrawal"
		id = withdrawalId
	} else {
		// the payment_id will appear on new deposits but appears to be removed from the response after 2 months
		id = this.SafeString(transaction, "depId")
		typeVar = "deposit"
	}
	var currencyId *string = this.SafeString(transaction, "ccy")
	var code *string = this.SafeCurrencyCode(currencyId)
	var network *string = nil
	var chain *string = this.SafeString(transaction, "chain")
	if chain != nil {
		var chainParts []string = strings.Split(*chain, "-")
		var networkParts any = this.ArraySlice(chainParts, 1)
		var networkId string = Join(networkParts, "-")
		network = this.NetworkIdToCode(networkId, code)
	}
	var amount *float64 = this.SafeNumber(transaction, "amt")
	var status *string = this.ParseTransactionStatus(this.SafeString(transaction, "state"))
	var txid *string = this.SafeString(transaction, "txId")
	var timestamp *int64 = this.SafeInteger(transaction, "ts")
	var feeCost any = nil
	if typeVar == "deposit" {
		feeCost = 0
	} else {
		feeCost = DerefScalar(this.SafeNumber(transaction, "fee"))
	}
	// todo parse tags
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"currency":    code,
		"amount":      amount,
		"network":     network,
		"addressFrom": addressFrom,
		"addressTo":   addressTo,
		"address":     address,
		"tagFrom":     nil,
		"tagTo":       tagTo,
		"tag":         tagTo,
		"status":      status,
		"type":        typeVar,
		"updated":     nil,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"internal":    nil,
		"comment":     nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     feeCost,
		},
	}
}

/**
 * @method
 * @name okx#fetchLeverage
 * @description fetch the set leverage for a market
 * @see https://www.okx.com/docs-v5/en/#rest-api-account-get-leverage
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.marginMode] 'cross' or 'isolated'
 * @returns {object} a [leverage structure]{@link https://docs.ccxt.com/?id=leverage-structure}
 */
func (this *Okx) FetchLeverageAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchLeverageBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Okx) fetchLeverageBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	// cross as default marginMode
	var defaultMarginMode *string = this.SafeString(params, "mgnMode", "cross")
	var marginModeparamsMarginModeVariable []any = this.HandleMarginModeAndParams("fetchLeverage", params, defaultMarginMode)
	var marginMode *string = SafeStringPtr(GetValue(marginModeparamsMarginModeVariable, 0))
	var paramsMarginMode map[string]any = MapTyped(GetValue(marginModeparamsMarginModeVariable, 1))
	if (marginMode == nil || *marginMode != "cross") && (marginMode == nil || *marginMode != "isolated") {
		panic(BadRequest(this.Id + " fetchLeverage() requires a marginMode parameter that must be either cross or isolated"))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"instId":  market["id"],
		"mgnMode": marginMode,
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateGetAccountLeverageInfo(this.Extend(request, paramsMarginMode))).Raw))
	//
	//     {
	//        "code": "0",
	//        "data": [
	//            {
	//                "instId": "BTC-USDT-SWAP",
	//                "lever": "5.00000000",
	//                "mgnMode": "isolated",
	//                "posSide": "net"
	//            }
	//        ],
	//        "msg": ""
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseLeverage(data, market)
	return nil
}
func (this *Okx) ParseLeverage(leverage any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId any = nil
	var marginMode *string = nil
	var longLeverage *int64 = nil
	var shortLeverage *int64 = nil
	for i := 0; i < GetArrayLength(leverage); i++ {
		var entry map[string]any = SafeMapTyped(leverage, i)
		marginMode = this.SafeStringLower(entry, "mgnMode")
		marketId = DerefScalar(this.SafeString(entry, "instId"))
		var positionSide *string = this.SafeStringLower(entry, "posSide")
		if positionSide != nil && *positionSide == "long" {
			longLeverage = this.SafeInteger(entry, "lever")
		} else if positionSide != nil && *positionSide == "short" {
			shortLeverage = this.SafeInteger(entry, "lever")
		} else {
			longLeverage = this.SafeInteger(entry, "lever")
			shortLeverage = this.SafeInteger(entry, "lever")
		}
	}
	return map[string]any{
		"info":          leverage,
		"symbol":        this.SafeSymbol(marketId, market),
		"marginMode":    marginMode,
		"longLeverage":  longLeverage,
		"shortLeverage": shortLeverage,
	}
}

