func (this *Okx) ParsePosition(position any, optionalArgs ...any) any {
	//
	//     {
	//        "adl": "3",
	//        "availPos": "1",
	//        "avgPx": "34131.1",
	//        "cTime": "1627227626502",
	//        "ccy": "USDT",
	//        "deltaBS": "",
	//        "deltaPA": "",
	//        "gammaBS": "",
	//        "gammaPA": "",
	//        "imr": "170.66093041794787",
	//        "instId": "BTC-USDT-SWAP",
	//        "instType": "SWAP",
	//        "interest": "0",
	//        "last": "34134.4",
	//        "lever": "2",
	//        "liab": "",
	//        "liabCcy": "",
	//        "liqPx": "12608.959083877446",
	//        "markPx": "4786.459271773621",
	//        "margin": "",
	//        "mgnMode": "cross",
	//        "mgnRatio": "140.49930117599155",
	//        "mmr": "1.3652874433435829",
	//        "notionalUsd": "341.5130010779638",
	//        "optVal": "",
	//        "pos": "1",
	//        "posCcy": "",
	//        "posId": "339552508062380036",
	//        "posSide": "long",
	//        "thetaBS": "",
	//        "thetaPA": "",
	//        "tradeId": "98617799",
	//        "uTime": "1627227626502",
	//        "upl": "0.0108608358957281",
	//        "uplRatio": "0.0000636418743944",
	//        "vegaBS": "",
	//        "vegaPA": ""
	//    }
	// history
	//    {
	//        "cTime":"1708351230102",
	//        "ccy":"USDT",
	//        "closeAvgPx":"1.2567",
	//        "closeTotalPos":"40",
	//        "direction":"short",
	//        "fee":"-0.0351036",
	//        "fundingFee":"0",
	//        "instId":"SUSHI-USDT-SWAP",
	//        "instType":"SWAP",
	//        "lever":"10.0",
	//        "liqPenalty":"0",
	//        "mgnMode":"isolated",
	//        "openAvgPx":"1.2462",
	//        "openMaxPos":"40",
	//        "pnl":"-0.42",
	//        "pnlRatio":"-0.0912982667308618",
	//        "posId":"666159086676836352",
	//        "realizedPnl":"-0.4551036",
	//        "triggerPx":"",
	//        "type":"2",
	//        "uTime":"1708354805699",
	//        "uly":"SUSHI-USDT"
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "instId")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, nil, "contract")
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var pos *string = this.SafeString(position, "pos") // 'pos' field: One way mode: 0 if position is not open, 1 if open | Two way (hedge) mode: -1 if short, 1 if long, 0 if position is not open
	var contractsAbs *string = Precise.StringAbs(pos)
	var side *string = this.SafeString2(position, "posSide", "direction")
	var hedged bool = (side == nil || *side != "net")
	var contracts *float64 = Float64PtrTyped(this.ParseNumber(contractsAbs))
	if GetValue(marketResolved, "margin") == true {
		// margin position
		if side != nil && *side == "net" {
			var posCcy *string = this.SafeString(position, "posCcy")
			var parsedCurrency *string = this.SafeCurrencyCode(posCcy)
			if parsedCurrency != nil {
				side = SafeStringPtr(func() string {
					if IsEqual(marketResolved["base"], parsedCurrency) {
						return "long"
					}
					return "short"
				}())
			}
		}
		if side == nil {
			side = this.SafeString(position, "direction")
		}
	} else {
		if pos != nil {
			if side != nil && *side == "net" {
				if Precise.StringGt(pos, "0") {
					side = SafeStringPtr("long")
				} else if Precise.StringLt(pos, "0") {
					side = SafeStringPtr("short")
				} else {
					side = nil
				}
			}
		}
	}
	var contractSize *float64 = this.SafeNumber(marketResolved, "contractSize")
	var contractSizeString *string = this.NumberToString(contractSize)
	var markPriceString *string = this.SafeString(position, "markPx")
	var notionalString *string = this.SafeString(position, "notionalUsd")
	if GetValue(marketResolved, "inverse") == true {
		notionalString = Precise.StringDiv(Precise.StringMul(contractsAbs, contractSizeString), markPriceString)
	}
	var notional *float64 = Float64PtrTyped(this.ParseNumber(notionalString))
	var marginMode *string = this.SafeString(position, "mgnMode")
	var initialMarginString *string = nil
	var entryPriceString *string = this.SafeString2(position, "avgPx", "openAvgPx")
	var unrealizedPnlString *string = this.SafeString(position, "upl")
	var leverageString *string = this.SafeString(position, "lever")
	var initialMarginPercentage any = nil
	var collateralString *string = nil
	if marginMode != nil && *marginMode == "cross" {
		initialMarginString = this.SafeString(position, "imr")
		collateralString = Precise.StringAdd(initialMarginString, unrealizedPnlString)
	} else if marginMode != nil && *marginMode == "isolated" {
		initialMarginPercentage = Precise.StringDiv("1", leverageString)
		collateralString = this.SafeString(position, "margin")
	}
	var maintenanceMarginString *string = this.SafeString(position, "mmr")
	var maintenanceMargin *float64 = Float64PtrTyped(this.ParseNumber(maintenanceMarginString))
	var maintenanceMarginPercentageString *string = Precise.StringDiv(maintenanceMarginString, notionalString)
	if initialMarginPercentage == nil {
		initialMarginPercentage = this.ParseNumber(Precise.StringDiv(initialMarginString, notionalString, 4))
	} else if initialMarginString == nil {
		if GetValue(marketResolved, "linear") == true {
			var initialMarginPercentageString *string = this.NumberToString(initialMarginPercentage)
			initialMarginString = Precise.StringMul(initialMarginPercentageString, notionalString)
		} else {
			initialMarginString = Precise.StringDiv(Precise.StringDiv(Precise.StringMul(contractsAbs, contractSizeString), entryPriceString), leverageString)
		}
	}
	var rounder string = "0.00005" // round to closest 0.01%
	var maintenanceMarginPercentage *float64 = Float64PtrTyped(this.ParseNumber(Precise.StringDiv(Precise.StringAdd(maintenanceMarginPercentageString, rounder), "1", 4)))
	var liquidationPrice *float64 = this.SafeNumber(position, "liqPx")
	var percentageString *string = this.SafeString(position, "uplRatio")
	var percentage *float64 = Float64PtrTyped(this.ParseNumber(Precise.StringMul(percentageString, "100")))
	var timestamp *int64 = this.SafeInteger(position, "cTime")
	var marginRatio *float64 = Float64PtrTyped(this.ParseNumber(Precise.StringDiv(maintenanceMarginString, collateralString, 4)))
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          this.SafeString(position, "posId"),
		"symbol":                      symbol,
		"notional":                    notional,
		"marginMode":                  marginMode,
		"liquidationPrice":            liquidationPrice,
		"entryPrice":                  this.ParseNumber(entryPriceString),
		"unrealizedPnl":               this.ParseNumber(unrealizedPnlString),
		"realizedPnl":                 this.SafeNumber(position, "realizedPnl"),
		"percentage":                  percentage,
		"contracts":                   contracts,
		"contractSize":                contractSize,
		"markPrice":                   this.ParseNumber(markPriceString),
		"lastPrice":                   this.SafeNumber(position, "closeAvgPx"),
		"side":                        side,
		"hedged":                      hedged,
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"lastUpdateTimestamp":         this.SafeInteger(position, "uTime"),
		"maintenanceMargin":           maintenanceMargin,
		"maintenanceMarginPercentage": maintenanceMarginPercentage,
		"collateral":                  this.ParseNumber(collateralString),
		"initialMargin":               this.ParseNumber(initialMarginString),
		"initialMarginPercentage":     this.ParseNumber(initialMarginPercentage),
		"leverage":                    this.ParseNumber(leverageString),
		"marginRatio":                 marginRatio,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
	})
}

/**
 * @method
 * @name okx#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://www.okx.com/docs-v5/en/#rest-api-funding-funds-transfer
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from
 * @param {string} toAccount account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Okx) TransferAsync(code any, amount any, fromAccount any, toAccount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Okx) transferBody(ch chan any, code any, amount any, fromAccount any, toAccount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	var fromId *string = this.SafeString(accountsByType, fromAccount, fromAccount)
	var toId *string = this.SafeString(accountsByType, toAccount, toAccount)
	var request map[string]any = map[string]any{
		"ccy":  currency["id"],
		"amt":  this.CurrencyToPrecision(code, amount),
		"type": "0",
		"from": fromId,
		"to":   toId,
	}
	if fromId != nil && *fromId == "master" {
		request["type"] = "1"
		request["subAcct"] = toId
		request["from"] = this.SafeString(params, "from", "6")
		request["to"] = this.SafeString(params, "to", "6")
	} else if toId != nil && *toId == "master" {
		request["type"] = "2"
		request["subAcct"] = fromId
		request["from"] = this.SafeString(params, "from", "6")
		request["to"] = this.SafeString(params, "to", "6")
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostAssetTransfer(this.Extend(request, params))).Raw))
	//
	//     {
	//         "code": "0",
	//         "msg": "",
	//         "data": [
	//             {
	//                 "transId": "754147",
	//                 "ccy": "USDT",
	//                 "from": "6",
	//                 "amt": "0.1",
	//                 "to": "18"
	//             }
	//         ]
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var rawTransfer map[string]any = MapTyped(this.SafeDict(data, 0, map[string]any{}))

	ch <- this.ParseTransfer(rawTransfer, currency)
	return nil
}
func (this *Okx) ParseTransfer(transfer any, optionalArgs ...any) any {
	//
	// transfer
	//
	//     {
	//         "transId": "754147",
	//         "ccy": "USDT",
	//         "from": "6",
	//         "amt": "0.1",
	//         "to": "18"
	//     }
	//
	// fetchTransfer
	//
	//     {
	//         "amt": "5",
	//         "ccy": "USDT",
	//         "from": "18",
	//         "instId": "",
	//         "state": "success",
	//         "subAcct": "",
	//         "to": "6",
	//         "toInstId": "",
	//         "transId": "464424732",
	//         "type": "0"
	//     }
	//
	// fetchTransfers
	//
	//     {
	//         "bal": "70.6874353780312913",
	//         "balChg": "-4.0000000000000000", // negative means "to funding", positive meand "from funding"
	//         "billId": "588900695232225299",
	//         "ccy": "USDT",
	//         "execType": "",
	//         "fee": "",
	//         "from": "18",
	//         "instId": "",
	//         "instType": "",
	//         "mgnMode": "",
	//         "notes": "To Funding Account",
	//         "ordId": "",
	//         "pnl": "",
	//         "posBal": "",
	//         "posBalChg": "",
	//         "price": "0",
	//         "subType": "12",
	//         "sz": "-4",
	//         "to": "6",
	//         "ts": "1686676866989",
	//         "type": "1"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString2(transfer, "transId", "billId")
	var currencyId *string = this.SafeString(transfer, "ccy")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var amount any = DerefScalar(this.SafeNumber(transfer, "amt"))
	var fromAccountId *string = this.SafeString(transfer, "from")
	var toAccountId *string = this.SafeString(transfer, "to")
	var accountsById map[string]any = SafeMapTyped(this.Options, "accountsById")
	var timestamp *int64 = this.SafeInteger(transfer, "ts")
	var balanceChange *string = this.SafeString(transfer, "sz")
	if balanceChange != nil {
		amount = this.ParseNumber(Precise.StringAbs(balanceChange))
	}
	return map[string]any{
		"info":      transfer,
		"id":        id,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"currency":  code,
		"amount":    amount,
		"fromAccount": func() any {
			if fromAccountId == nil {
				return nil
			}
			return this.SafeString(accountsById, fromAccountId)
		}(),
		"toAccount": func() any {
			if toAccountId == nil {
				return nil
			}
			return this.SafeString(accountsById, toAccountId)
		}(),
		"status": this.ParseTransferStatus(this.SafeString(transfer, "state")),
	}
}
func (this *Okx) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"success": "ok",
	}
	if status == nil {
		return nil
	}
	return this.SafeString(statuses, status, status)
}

