func (this *Okx) modifyMarginHelperBody(ch chan any, symbol any, amount any, typeVar any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var posSide *string = this.SafeString(params, "posSide", "net")
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, []any{"posSide"}))
	var request map[string]any = map[string]any{
		"instId":  market["id"],
		"amt":     amount,
		"type":    typeVar,
		"posSide": posSide,
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostAccountPositionMarginBalance(this.Extend(request, paramsOmitted))).Raw))
	//
	//     {
	//       "code": "0",
	//       "data": [
	//         {
	//           "amt": "0.01",
	//           "instId": "ETH-USD-SWAP",
	//           "posSide": "net",
	//           "type": "reduce"
	//         }
	//       ],
	//       "msg": ""
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var entry map[string]any = MapTyped(this.SafeDict(data, 0, map[string]any{}))
	var errorCode *string = this.SafeString(response, "code")

	ch <- this.Extend(this.ParseMarginModification(entry, market), map[string]any{
		"status": func() string {
			if errorCode != nil && *errorCode == "0" {
				return "ok"
			}
			return "failed"
		}(),
	})
	return nil
}
func (this *Okx) ParseMarginModification(data any, optionalArgs ...any) any {
	//
	// addMargin/reduceMargin
	//
	//    {
	//        "amt": "0.01",
	//        "instId": "ETH-USD-SWAP",
	//        "posSide": "net",
	//        "type": "reduce"
	//    }
	//
	// fetchMarginAdjustmentHistory
	//
	//    {
	//        bal: '67621.4325135010619812',
	//        balChg: '-10.0000000000000000',
	//        billId: '691293628710342659',
	//        ccy: 'USDT',
	//        clOrdId: '',
	//        execType: '',
	//        fee: '0',
	//        fillFwdPx: '',
	//        fillIdxPx: '',
	//        fillMarkPx: '',
	//        fillMarkVol: '',
	//        fillPxUsd: '',
	//        fillPxVol: '',
	//        fillTime: '1711089244850',
	//        from: '',
	//        instId: 'XRP-USDT-SWAP',
	//        instType: 'SWAP',
	//        interest: '0',
	//        mgnMode: 'isolated',
	//        notes: '',
	//        ordId: '',
	//        pnl: '0',
	//        posBal: '73.12',
	//        posBalChg: '10.00',
	//        px: '',
	//        subType: '160',
	//        sz: '10',
	//        tag: '',
	//        to: '',
	//        tradeId: '0',
	//        ts: '1711089244699',
	//        type: '6'
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var amountRaw *string = this.SafeString2(data, "amt", "posBalChg")
	var typeRaw *string = this.SafeString(data, "type")
	// ledger uses numeric '6' (+/- amount); addMargin/reduceMargin already send 'add'/'reduce'
	var typeVar any = nil
	if typeRaw != nil && *typeRaw == "6" {
		typeVar = func() string {
			if Precise.StringGt(amountRaw, "0") {
				return "add"
			}
			return "reduce"
		}()
	} else {
		typeVar = typeRaw
	}
	var amount *string = Precise.StringAbs(amountRaw)
	var marketId *string = this.SafeString(data, "instId")
	var responseMarket map[string]any = this.SafeMarket(marketId, market)
	var code any = func() any {
		if GetValue(responseMarket, "inverse") == true {
			return responseMarket["base"]
		}
		return responseMarket["quote"]
	}()
	var timestamp *int64 = this.SafeInteger(data, "ts")
	return map[string]any{
		"info":       data,
		"symbol":     responseMarket["symbol"],
		"type":       typeVar,
		"marginMode": "isolated",
		"amount":     this.ParseNumber(amount),
		"code":       code,
		"total":      nil,
		"status":     nil,
		"timestamp":  timestamp,
		"datetime":   this.Iso8601(timestamp),
	}
}

