/**
 * @method
 * @name okx#fetchMarketLeverageTiers
 * @description retrieve information on the maximum leverage, and maintenance margin for trades of varying trade sizes for a single market
 * @see https://www.okx.com/docs-v5/en/#rest-api-public-data-get-position-tiers
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.marginMode] 'cross' or 'isolated'
 * @returns {object} a [leverage tiers structure]{@link https://docs.ccxt.com/?id=leverage-tiers-structure}
 */
func (this *Okx) FetchMarketLeverageTiersAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketLeverageTiersBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Okx) fetchMarketLeverageTiersBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var typeVar any = func() any {
		if GetValue(market, "spot") == true {
			return "MARGIN"
		}
		return this.ConvertToInstrumentType(market["type"])
	}()
	var uly *string = this.SafeString(market["info"], "uly")
	if (uly == nil) || (uly != nil && *uly == "") {
		if !IsEqual(typeVar, "MARGIN") {
			panic(BadRequest(Add(this.Id+" fetchMarketLeverageTiers() cannot fetch leverage tiers for ", symbol)))
		}
	}
	// cross as default marginMode
	var defaultMarginMode *string = this.SafeString(params, "tdMode", "cross")
	var marginModeparamsMarginModeVariable []any = this.HandleMarginModeAndParams("fetchMarketLeverageTiers", params, defaultMarginMode)
	var marginMode *string = SafeStringPtr(GetValue(marginModeparamsMarginModeVariable, 0))
	var paramsMarginMode map[string]any = MapTyped(GetValue(marginModeparamsMarginModeVariable, 1))
	var request map[string]any = map[string]any{
		"instType": typeVar,
		"tdMode":   marginMode,
		"uly":      uly,
	}
	if IsEqual(typeVar, "MARGIN") {
		request["instId"] = market["id"]
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetPublicPositionTiers(this.Extend(request, paramsMarginMode))).Raw))
	//
	//    {
	//        "code": "0",
	//        "data": [
	//            {
	//                "baseMaxLoan": "500",
	//                "imr": "0.1",
	//                "instId": "ETH-USDT",
	//                "maxLever": "10",
	//                "maxSz": "500",
	//                "minSz": "0",
	//                "mmr": "0.03",
	//                "optMgnFactor": "0",
	//                "quoteMaxLoan": "200000",
	//                "tier": "1",
	//                "uly": ""
	//            },
	//            ...
	//        ]
	//    }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseMarketLeverageTiers(data, market)
	return nil
}
func (this *Okx) ParseMarketLeverageTiers(info any, optionalArgs ...any) any {
	/**
	 * @ignore
	 * @method
	 * @param {object} info Exchange response for 1 market
	 * @param {object} market CCXT market
	 */
	//
	//    [
	//        {
	//            "baseMaxLoan": "500",
	//            "imr": "0.1",
	//            "instId": "ETH-USDT",
	//            "maxLever": "10",
	//            "maxSz": "500",
	//            "minSz": "0",
	//            "mmr": "0.03",
	//            "optMgnFactor": "0",
	//            "quoteMaxLoan": "200000",
	//            "tier": "1",
	//            "uly": ""
	//        },
	//        ...
	//    ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var tiers []any = []any{}
	for i := 0; i < GetArrayLength(info); i++ {
		var tier map[string]any = SafeMapTyped(info, i)
		var marketId *string = this.SafeString(tier, "instId")
		tiers = append(tiers, map[string]any{
			"tier":                  this.SafeInteger(tier, "tier"),
			"symbol":                this.SafeSymbol(marketId, market),
			"currency":              this.SafeString(market, "quote"),
			"minNotional":           this.SafeNumber(tier, "minSz"),
			"maxNotional":           this.SafeNumber(tier, "maxSz"),
			"maintenanceMarginRate": this.SafeNumber(tier, "mmr"),
			"maxLeverage":           this.SafeNumber(tier, "maxLever"),
			"info":                  tier,
		})
	}
	return tiers
}

/**
 * @method
 * @name okx#fetchBorrowInterest
 * @description fetch the interest owed b the user for borrowing currency for margin trading
 * @see https://www.okx.com/docs-v5/en/#rest-api-account-get-interest-accrued-data
 * @param {string} code the unified currency code for the currency of the interest
 * @param {string} symbol the market symbol of an isolated margin market, if undefined, the interest for cross margin markets is returned
 * @param {int} [since] timestamp in ms of the earliest time to receive interest records for
 * @param {int} [limit] the number of [borrow interest structures]{@link https://docs.ccxt.com/?id=borrow-interest-structure} to retrieve
 * @param {object} [params] exchange specific parameters
 * @param {int} [params.type] Loan type 1 - VIP loans 2 - Market loans *Default is Market loans*
 * @param {string} [params.marginMode] 'cross' or 'isolated'
 * @returns {object[]} An list of [borrow interest structures]{@link https://docs.ccxt.com/?id=borrow-interest-structure}
 */
func (this *Okx) FetchBorrowInterestAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBorrowInterestBody(ch, optionalArgs...)
	return ch
}
func (this *Okx) fetchBorrowInterestBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var symbol *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 3, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 4, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	// cross as default marginMode
	var defaultMarginMode *string = this.SafeString(params, "mgnMode", "cross")
	var marginModeparamsMarginModeVariable []any = this.HandleMarginModeAndParams("fetchBorrowInterest", params, defaultMarginMode)
	var marginMode *string = SafeStringPtr(GetValue(marginModeparamsMarginModeVariable, 0))
	var paramsMarginMode map[string]any = MapTyped(GetValue(marginModeparamsMarginModeVariable, 1))
	var request map[string]any = map[string]any{
		"mgnMode": marginMode,
	}
	var market map[string]any = nil
	if code != nil {
		var currency map[string]any = this.Currency(code)
		request["ccy"] = currency["id"]
	}
	if since != nil {
		request["before"] = Subtract(since, 1)
	}
	if limit != nil {
		request["limit"] = limit
	}
	if symbol != nil {
		market = this.Market(symbol)
		request["instId"] = GetValue(market, "id")
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateGetAccountInterestAccrued(this.Extend(request, paramsMarginMode))).Raw))
	//
	//    {
	//        "code": "0",
	//        "data": [
	//            {
	//                "ccy": "USDT",
	//                "instId": "",
	//                "interest": "0.0003960833333334",
	//                "interestRate": "0.0000040833333333",
	//                "liab": "97",
	//                "mgnMode": "",
	//                "ts": "1637312400000",
	//                "type": "1"
	//            },
	//            ...
	//        ],
	//        "msg": ""
	//    }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var interest any = this.ParseBorrowInterests(data)

	ch <- this.FilterByCurrencySinceLimit(interest, code, since, limit)
	return nil
}
func (this *Okx) ParseBorrowInterest(info any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var instId *string = this.SafeString(info, "instId")
	var marketResolved any = func() any {
		if instId != nil {
			return this.SafeMarket(instId, market)
		}
		return market
	}()
	var timestamp *int64 = this.SafeInteger(info, "ts")
	return map[string]any{
		"info":           info,
		"symbol":         this.SafeString(marketResolved, "symbol"),
		"currency":       this.SafeCurrencyCode(this.SafeString(info, "ccy")),
		"interest":       this.SafeNumber(info, "interest"),
		"interestRate":   this.SafeNumber(info, "interestRate"),
		"amountBorrowed": this.SafeNumber(info, "liab"),
		"marginMode":     this.SafeString(info, "mgnMode"),
		"timestamp":      timestamp,
		"datetime":       this.Iso8601(timestamp),
	}
}

