func (this *Okx) ParseOption(chain any, optionalArgs ...any) any {
	//
	//     {
	//         "instType": "OPTION",
	//         "instId": "BTC-USD-241227-60000-P",
	//         "last": "",
	//         "lastSz": "0",
	//         "askPx": "",
	//         "askSz": "0",
	//         "bidPx": "",
	//         "bidSz": "0",
	//         "open24h": "",
	//         "high24h": "",
	//         "low24h": "",
	//         "volCcy24h": "0",
	//         "vol24h": "0",
	//         "ts": "1711176035035",
	//         "sodUtc0": "",
	//         "sodUtc8": ""
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var market map[string]any = GetArgMap(optionalArgs, 1, nil)
	_ = market
	var marketId *string = this.SafeString(chain, "instId")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(chain, "ts")
	return map[string]any{
		"info":              chain,
		"currency":          nil,
		"symbol":            marketResolved["symbol"],
		"timestamp":         timestamp,
		"datetime":          this.Iso8601(timestamp),
		"impliedVolatility": nil,
		"openInterest":      nil,
		"bidPrice":          this.SafeNumber(chain, "bidPx"),
		"askPrice":          this.SafeNumber(chain, "askPx"),
		"midPrice":          nil,
		"markPrice":         nil,
		"lastPrice":         this.SafeNumber(chain, "last"),
		"underlyingPrice":   nil,
		"change":            nil,
		"percentage":        nil,
		"baseVolume":        this.SafeNumber(chain, "volCcy24h"),
		"quoteVolume":       nil,
	}
}

