/**
 * @method
 * @name okx#fetchConvertTradeHistory
 * @description fetch the users history of conversion trades
 * @see https://www.okx.com/docs-v5/en/#funding-account-rest-api-get-convert-history
 * @param {string} [code] the unified currency code
 * @param {int} [since] the earliest time in ms to fetch conversions for
 * @param {int} [limit] the maximum number of conversion structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest conversion to fetch
 * @returns {object[]} a list of [conversion structures]{@link https://docs.ccxt.com/?id=conversion-structure}
 */
func (this *Okx) FetchConvertTradeHistoryAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchConvertTradeHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Okx) fetchConvertTradeHistoryBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var request map[string]any = map[string]any{}
	var requestUntilparamsUntilVariable []any = this.HandleUntilOption("after", request, params)
	var requestUntil map[string]any = MapTyped(GetValue(requestUntilparamsUntilVariable, 0))
	var paramsUntil map[string]any = MapTyped(GetValue(requestUntilparamsUntilVariable, 1))
	if since != nil {
		AddElementToObject(requestUntil, "before", since)
	}
	if limit != nil {
		AddElementToObject(requestUntil, "limit", limit)
	}

	response := (<-this.PrivateGetAssetConvertHistory(this.Extend(requestUntil, paramsUntil)))
	PanicOnError(response)
	//
	//     {
	//         "code": "0",
	//         "data": [
	//             {
	//                 "clTReqId": "",
	//                 "instId": "ETH-USDT",
	//                 "side": "buy",
	//                 "fillPx": "2932.401044",
	//                 "baseCcy": "ETH",
	//                 "quoteCcy": "USDT",
	//                 "fillBaseSz": "0.01023052",
	//                 "state": "fullyFilled",
	//                 "tradeId": "trader16461885203381437",
	//                 "fillQuoteSz": "30",
	//                 "ts": "1646188520000"
	//             }
	//         ],
	//         "msg": ""
	//     }
	//
	var rows []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseConversions(rows, code, "baseCcy", "quoteCcy", since, limit)
	return nil
}
func (this *Okx) ParseConversion(conversion any, optionalArgs ...any) any {
	//
	// fetchConvertQuote
	//
	//     {
	//         "baseCcy": "ETH",
	//         "baseSz": "0.01023052",
	//         "clQReqId": "",
	//         "cnvtPx": "2932.40104429",
	//         "origRfqSz": "30",
	//         "quoteCcy": "USDT",
	//         "quoteId": "quoterETH-USDT16461885104612381",
	//         "quoteSz": "30",
	//         "quoteTime": "1646188510461",
	//         "rfqSz": "30",
	//         "rfqSzCcy": "USDT",
	//         "side": "buy",
	//         "ttlMs": "10000"
	//     }
	//
	// createConvertTrade
	//
	//     {
	//         "baseCcy": "ETH",
	//         "clTReqId": "",
	//         "fillBaseSz": "0.01023052",
	//         "fillPx": "2932.40104429",
	//         "fillQuoteSz": "30",
	//         "instId": "ETH-USDT",
	//         "quoteCcy": "USDT",
	//         "quoteId": "quoterETH-USDT16461885104612381",
	//         "side": "buy",
	//         "state": "fullyFilled",
	//         "tradeId": "trader16461885203381437",
	//         "ts": "1646188520338"
	//     }
	//
	// fetchConvertTrade, fetchConvertTradeHistory
	//
	//     {
	//         "clTReqId": "",
	//         "instId": "ETH-USDT",
	//         "side": "buy",
	//         "fillPx": "2932.401044",
	//         "baseCcy": "ETH",
	//         "quoteCcy": "USDT",
	//         "fillBaseSz": "0.01023052",
	//         "state": "fullyFilled",
	//         "tradeId": "trader16461885203381437",
	//         "fillQuoteSz": "30",
	//         "ts": "1646188520000"
	//     }
	//
	var fromCurrency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = fromCurrency
	var toCurrency map[string]any = GetArgMap(optionalArgs, 1, nil)
	_ = toCurrency
	var timestamp *int64 = this.SafeInteger2(conversion, "quoteTime", "ts")
	var fromCoin *string = this.SafeString(conversion, "baseCcy")
	var fromCode *string = this.SafeCurrencyCode(fromCoin, fromCurrency)
	var to *string = this.SafeString(conversion, "quoteCcy")
	var toCode *string = this.SafeCurrencyCode(to, toCurrency)
	return map[string]any{
		"info":         conversion,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"id":           this.SafeStringN(conversion, []any{"clQReqId", "tradeId", "quoteId"}),
		"fromCurrency": fromCode,
		"fromAmount":   this.SafeNumber2(conversion, "baseSz", "fillBaseSz"),
		"toCurrency":   toCode,
		"toAmount":     this.SafeNumber2(conversion, "quoteSz", "fillQuoteSz"),
		"price":        this.SafeNumber2(conversion, "cnvtPx", "fillPx"),
		"fee":          nil,
	}
}

