func (this *Okx) FetchConvertCurrenciesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchConvertCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Okx) fetchConvertCurrenciesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}

	response := (<-this.PrivateGetAssetConvertCurrencies(params))
	PanicOnError(response)
	//
	//     {
	//         "code": "0",
	//         "data": [
	//             {
	//                 "ccy": "BTC",
	//                 "max": "",
	//                 "min": ""
	//             },
	//         ],
	//         "msg": ""
	//     }
	//
	var result map[string]any = map[string]any{}
	var data []any = SafeListTyped(response, "data")
	for i := 0; i < len(data); i++ {
		var entry any = func() any {
			if i >= 0 && i < len(data) {
				return DerefScalar(data[i])
			}
			return nil
		}()
		var id *string = this.SafeString(entry, "ccy")
		var code *string = this.SafeCurrencyCode(id)
		if code != nil {
			result[*code] = map[string]any{
				"info":      entry,
				"id":        id,
				"code":      code,
				"networks":  nil,
				"type":      nil,
				"name":      nil,
				"active":    nil,
				"deposit":   nil,
				"withdraw":  nil,
				"fee":       nil,
				"precision": nil,
				"limits": map[string]any{
					"amount": map[string]any{
						"min": this.SafeNumber(entry, "min"),
						"max": this.SafeNumber(entry, "max"),
					},
					"withdraw": map[string]any{
						"min": nil,
						"max": nil,
					},
					"deposit": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
				"created": nil,
			}
		}
	}

	ch <- result
	return nil
}
func (this *Okx) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil // fallback to default error handler
	}
	//
	//    {
	//        "code": "1",
	//        "data": [
	//            {
	//                "clOrdId": "",
	//                "ordId": "",
	//                "sCode": "51119",
	//                "sMsg": "Order placement failed due to insufficient balance. ",
	//                "tag": ""
	//            }
	//        ],
	//        "msg": ""
	//    },
	//    {
	//        "code": "58001",
	//        "data": [],
	//        "msg": "Incorrect trade password"
	//    }
	//
	var code *string = this.SafeString(response, "code")
	if (code == nil || *code != "0") && (code == nil || *code != "2") {
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		var data []any = SafeListTyped(response, "data")
		for i := 0; i < len(data); i++ {
			var error map[string]any = SafeMapTyped(data, i)
			var errorCode *string = this.SafeString(error, "sCode")
			var message *string = this.SafeString(error, "sMsg")
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		}
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

/**
 * @method
 * @name okx#fetchMarginAdjustmentHistory
 * @description fetches the history of margin added or reduced from contract isolated positions
 * @see https://www.okx.com/docs-v5/en/#trading-account-rest-api-get-bills-details-last-7-days
 * @see https://www.okx.com/docs-v5/en/#trading-account-rest-api-get-bills-details-last-3-months
 * @param {string} [symbol] not used by okx fetchMarginAdjustmentHistory
 * @param {string} [type] "add" or "reduce"
 * @param {int} [since] the earliest time in ms to fetch margin adjustment history for
 * @param {int} [limit] the maximum number of entries to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.auto] true if fetching auto margin increases
 * @returns {object[]} a list of [margin structures]{@link https://docs.ccxt.com/?id=margin-loan-structure}
 */
func (this *Okx) FetchMarginAdjustmentHistoryAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarginAdjustmentHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Okx) fetchMarginAdjustmentHistoryBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var typeVar *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = typeVar
	var since *float64 = GetArgFloat64Ptr(optionalArgs, 2, nil)
	_ = since
	var limit *float64 = GetArgFloat64Ptr(optionalArgs, 3, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 4, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var auto *bool = this.SafeBool(params, "auto")
	if typeVar == nil {
		panic(ArgumentsRequired(this.Id + " fetchMarginAdjustmentHistory () requires a type argument"))
	}
	var isAdd bool = (typeVar != nil && *typeVar == "add")
	var subType string = func() string {
		if isAdd {
			return "160"
		}
		return "161"
	}()
	if auto != nil && *auto == true {
		if isAdd {
			subType = "162"
		} else {
			panic(BadRequest(this.Id + " cannot fetch margin adjustments for type " + *typeVar))
		}
	}
	var request map[string]any = map[string]any{
		"subType": subType,
		"mgnMode": "isolated",
	}
	var until *int64 = this.SafeInteger(params, "until")
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, "until"))
	if since != nil {
		request["startTime"] = since
	}
	if limit != nil {
		request["limit"] = limit
	}
	if until != nil {
		request["endTime"] = until
	}
	var response map[string]any = nil
	var now int64 = this.Milliseconds()
	var oneWeekAgo int64 = now - 604800000
	var threeMonthsAgo int64 = now - 7776000000
	if (since == nil) || (IsGreaterThan(since, oneWeekAgo)) {

		response = MapTyped(PanicOnError((<-this.PrivateGetAccountBills(this.Extend(request, paramsOmitted))).Raw))
	} else if IsGreaterThan(since, threeMonthsAgo) {

		response = MapTyped(PanicOnError((<-this.PrivateGetAccountBillsArchive(this.Extend(request, paramsOmitted))).Raw))
	} else {
		panic(BadRequest(this.Id + " fetchMarginAdjustmentHistory () cannot fetch margin adjustments older than 3 months"))
	}
	//
	//    {
	//        code: '0',
	//        data: [
	//            {
	//                bal: '67621.4325135010619812',
	//                balChg: '-10.0000000000000000',
	//                billId: '691293628710342659',
	//                ccy: 'USDT',
	//                clOrdId: '',
	//                execType: '',
	//                fee: '0',
	//                fillFwdPx: '',
	//                fillIdxPx: '',
	//                fillMarkPx: '',
	//                fillMarkVol: '',
	//                fillPxUsd: '',
	//                fillPxVol: '',
	//                fillTime: '1711089244850',
	//                from: '',
	//                instId: 'XRP-USDT-SWAP',
	//                instType: 'SWAP',
	//                interest: '0',
	//                mgnMode: 'isolated',
	//                notes: '',
	//                ordId: '',
	//                pnl: '0',
	//                posBal: '73.12',
	//                posBalChg: '10.00',
	//                px: '',
	//                subType: '160',
	//                sz: '10',
	//                tag: '',
	//                to: '',
	//                tradeId: '0',
	//                ts: '1711089244699',
	//                type: '6'
	//            }
	//        ],
	//        msg: ''
	//    }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var modifications any = this.ParseMarginModifications(data)

	ch <- this.FilterBySymbolSinceLimit(modifications, symbol, since, limit)
	return nil
}

/**
 * @method
 * @name okx#fetchPositionsHistory
 * @description fetches historical positions
 * @see https://www.okx.com/docs-v5/en/#trading-account-rest-api-get-positions-history
 * @param {string} [symbols] unified market symbols
 * @param {int} [since] timestamp in ms of the earliest position to fetch
 * @param {int} [limit] the maximum amount of records to fetch, default=100, max=100
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @param {string} [params.marginMode] "cross" or "isolated"
 *
 * EXCHANGE SPECIFIC PARAMETERS
 * @param {string} [params.instType] margin, swap, futures or option
 * @param {string} [params.type] the type of latest close position 1: close position partially, 2：close all, 3：liquidation, 4：partial liquidation; 5：adl, is it is the latest type if there are several types for the same position
 * @param {string} [params.posId] position id, there is attribute expiration, the posid will be expired if it is more than 30 days after the last full close position, then position will use new posid
 * @param {string} [params.before] timestamp in ms of the earliest position to fetch based on the last update time of the position
 * @param {string} [params.after] timestamp in ms of the latest position to fetch based on the last update time of the position
 * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
 */
func (this *Okx) FetchPositionsHistoryAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchPositionsHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Okx) fetchPositionsHistoryBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var marginMode *string = this.SafeString(params, "marginMode")
	var instType *string = this.SafeStringUpper(params, "instType")
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, []any{"until", "marginMode", "instType"}))
	var limitResolved int64 = func() int64 {
		if limit == nil {
			return 100
		}
		return *limit
	}()
	var request map[string]any = map[string]any{
		"limit": limitResolved,
	}
	if symbols != nil {
		var symbolsLength int = len(symbols)
		if symbolsLength == 1 {
			var market map[string]any = this.Market(GetValue(symbols, 0))
			request["instId"] = market["id"]
		}
	}
	if marginMode != nil {
		request["mgnMode"] = marginMode
	}
	if instType != nil {
		request["instType"] = instType
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateGetAccountPositionsHistory(this.Extend(request, paramsOmitted))).Raw))
	//
	//    {
	//        code: '0',
	//        data: [
	//            {
	//                cTime: '1708735940395',
	//                ccy: 'USDT',
	//                closeAvgPx: '0.6330444444444444',
	//                closeTotalPos: '27',
	//                direction: 'long',
	//                fee: '-1.69566',
	//                fundingFee: '-11.870404179341788',
	//                instId: 'XRP-USDT-SWAP',
	//                instType: 'SWAP',
	//                lever: '3.0',
	//                liqPenalty: '0',
	//                mgnMode: 'cross',
	//                openAvgPx: '0.623',
	//                openMaxPos: '15',
	//                pnl: '27.11999999999988',
	//                pnlRatio: '0.0241732402722634',
	//                posId: '681423155054862336',
	//                realizedPnl: '13.553935820658092',
	//                triggerPx: '',
	//                type: '2',
	//                uTime: '1711088748170',
	//                uly: 'XRP-USDT'
	//            },
	//            ...
	//        ],
	//        msg: ''
	//    }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var positions any = this.ParsePositions(data, symbols, paramsOmitted)

	ch <- this.FilterBySinceLimit(positions, since, limitResolved)
	return nil
}

